package io.undertow.protocols.http2;

import io.undertow.connector.PooledByteBuffer;
import io.undertow.server.protocol.framed.SendFrameHeader;
import io.undertow.util.ImmediatePooledByteBuffer;
import org.junit.jupiter.api.Test;

import java.nio.ByteBuffer;

import static org.junit.jupiter.api.Assertions.*;

public class Http2DataStreamSinkChannelCreateFrameHeaderImplTests {

    @Test
    void testSendFrameHeaderWithTrailer() {
        ByteBuffer trailerBuf = ByteBuffer.wrap(new byte[]{1, 2, 3});
        PooledByteBuffer pooled = new ImmediatePooledByteBuffer(ByteBuffer.allocate(16));

        SendFrameHeader header = new SendFrameHeader(5, pooled, true, trailerBuf);

        assertEquals(5, header.getRemainingInBuffer(), "Remaining in buffer should match the provided value");
        assertSame(pooled, header.getByteBuffer(), "Header should hold the exact provided PooledByteBuffer");
        assertTrue(header.isAnotherFrameRequired(), "Indicator for another frame should be true when set");
        ByteBuffer trailer = header.getTrailer();
        assertNotNull(trailer, "Trailer should be present when provided");
        assertEquals(trailerBuf.array().length, trailer.remaining(), "Trailer length should match provided trailer content");
        // Validate some content to ensure trailer buffer is preserved
        assertEquals(1, trailer.get(0));
        assertEquals(3, trailer.get(2));
    }

    @Test
    void testSendFrameHeaderWithoutTrailer() {
        ByteBuffer b = ByteBuffer.allocate(8);
        PooledByteBuffer pooled = new ImmediatePooledByteBuffer(b);

        SendFrameHeader header = new SendFrameHeader(10, pooled);

        assertEquals(10, header.getRemainingInBuffer(), "Remaining in buffer should be as initialized");
        assertSame(pooled, header.getByteBuffer(), "Header should reference the provided PooledByteBuffer");
        assertFalse(header.isAnotherFrameRequired(), "By default, there is no requirement for another frame");
        assertNull(header.getTrailer(), "Trailer should be null when not provided");
    }

    @Test
    void testSendFrameHeaderWithNullBuffer() {
        SendFrameHeader header = new SendFrameHeader(7, null);

        assertEquals(7, header.getRemainingInBuffer(), "Remaining in buffer should reflect initialization value");
        assertNull(header.getByteBuffer(), "ByteBuffer should be null when not provided");
        assertFalse(header.isAnotherFrameRequired(), "Default should indicate no additional frame");
        assertNull(header.getTrailer(), "Trailer should be null when not provided");
    }
}

